"use client";

import { Eye } from "lucide-react";
import { useVisitorCount } from "@/hooks/use-visitor-count";
import { cn } from "@/lib/utils";

export function VisitorCount({ className }: { className?: string }) {
  const { count, loading, error } = useVisitorCount();
  if (error) return null;

  return (
    <div role="status" className={cn("inline-flex items-center gap-2.5 rounded-full bg-muted px-4 py-2.5 text-sm text-muted-foreground", className)}>
      <Eye aria-hidden="true" className="size-4" />
      {loading ? (
        <span>Loading visitor count…</span>
      ) : (
        <span><strong className="font-semibold tabular-nums text-foreground">{count.toLocaleString()}</strong> unique {count === 1 ? "visitor" : "visitors"}</span>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { getOrCreateVisitorId } from "@/lib/visitor-identity";

export function useVisitorCount() {
  const [state, setState] = useState({ count: 0, loading: true, error: null as string | null });

  useEffect(() => {
    const controller = new AbortController();
    async function trackVisit() {
      try {
        const response = await fetch("/api/visitors", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ fingerprint: getOrCreateVisitorId() }),
          cache: "no-store",
          signal: controller.signal,
        });
        const data = await response.json();
        if (!response.ok || !data.success || !Number.isSafeInteger(data.uniqueVisitors) || data.uniqueVisitors < 0) {
          throw new Error("Visitor count is temporarily unavailable");
        }
        if (!controller.signal.aborted) {
          setState({ count: data.uniqueVisitors, loading: false, error: null });
        }
      } catch {
        if (!controller.signal.aborted) {
          setState({ count: 0, loading: false, error: "Visitor count is temporarily unavailable" });
        }
      }
    }
    void trackVisit();
    return () => controller.abort();
  }, []);

  return state;
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

const STORAGE_KEY = "obsidianui_visitor_id";
let sessionVisitorId: string | undefined;

export function getOrCreateVisitorId(): string {
  if (typeof window === "undefined") return "";
  if (sessionVisitorId) return sessionVisitorId;
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored && /^[a-zA-Z0-9_-]{1,128}$/.test(stored)) {
      sessionVisitorId = stored;
      return stored;
    }
  } catch {
    // Storage may be unavailable in private or embedded browsing contexts.
  }
  sessionVisitorId = window.crypto.randomUUID();
  try {
    window.localStorage.setItem(STORAGE_KEY, sessionVisitorId);
  } catch {
    // The memory ID remains stable for this page session.
  }
  return sessionVisitorId;
}
